// S21 acceptance (TICK-749): helpers for folder S21. Its requests wait for a
// backfill (minutes) and run p95 cells, longer than an access token lives
// (300 s), so every call signs in again when its token is close to expiry.
// Generated by docs/acceptance/guide/build/collection.py; edit it there.
const crypto = require('crypto');
const USERS = {
  admin_a_token: ['admin_a_username', 'admin_a_password'],
  alice_token: ['alice_username', 'alice_password'],
  bob_token: ['bob_username', 'bob_password'],
};

module.exports = (N, bru) => {
  const T = {
    // The token in v, signed in again when it expires within 90 s.
    async fresh(v) {
      const t = bru.getVar(v);
      if (t && N.jwt(t).exp * 1000 - Date.now() > 90000) return t;
      const [u, p] = USERS[v];
      const r = await N.token(N.v(u), N.v(p));
      if (r.status !== 200) throw new Error(`sign-in again for ${v}: HTTP ${r.status}`);
      bru.setVar(v, r.data.access_token);
      return r.data.access_token;
    },
    async call(v, method, path, data, headers = {}) {
      const h = { Authorization: 'Bearer ' + (await T.fresh(v)), ...headers };
      if (data !== undefined && !h['Content-Type']) h['Content-Type'] = 'application/json';
      const t0 = Date.now();
      const r = await N.send({ url: N.url('{{core_url}}' + path), method, headers: h, data });
      return { status: r.status, data: r.data, ms: Date.now() - t0 };
    },
    list(v, query) { return T.call(v, 'GET', '/api/v1/records/incident?' + query); },
    // Every record a filter lists, page by page (limit 200, next_cursor).
    async all(v, query) {
      const items = [];
      let cursor = null, first = null, pages = 0;
      do {
        const r = await T.list(v, query + '&limit=200' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''));
        if (r.status !== 200) throw new Error(`list ${query} as ${v}: HTTP ${r.status} ${JSON.stringify(r.data)}`);
        if (!first) first = r.data;
        items.push(...r.data.items);
        cursor = r.data.next_cursor;
        pages++;
      } while (cursor);
      return { items, ids: items.map(i => i.id), first, pages };
    },
    // md5 of the ids sorted as strings and joined by ',' (as tools/expect.sql).
    md5: (ids) => crypto.createHash('md5').update([...ids].sort().join(',')).digest('hex'),
    create(v, key, data) {
      return T.call(v, 'POST', '/api/v1/records/incident', { data }, { 'Idempotency-Key': key });
    },
    patch(v, key, id, version, data) {
      return T.call(v, 'PATCH', '/api/v1/records/incident/' + id, { data },
        { 'Idempotency-Key': key, 'Content-Type': 'application/merge-patch+json', 'If-Match': `W/"${version}"` });
    },
    // One p95 cell: `clients` callers list with `query` for `seconds` (after
    // 2 s of warm-up that is not counted), each paced to rate/clients
    // requests a second so the tenant stays under its 50/s rate limit.
    async cell(v, query, seconds, { clients = 8, rate = 40 } = {}) {
      const tok = await T.fresh(v);
      const url = N.url('{{core_url}}/api/v1/records/incident' + (query ? '?' + query : ''));
      const period = (clients * 1000) / rate;
      const ms = [], statuses = {};
      const warm = Date.now() + 2000, end = warm + seconds * 1000;
      const client = async () => {
        while (Date.now() < end) {
          const t0 = Date.now();
          const r = await N.send({ url, method: 'GET', headers: { Authorization: 'Bearer ' + tok } });
          const t1 = Date.now();
          if (t0 >= warm) {
            ms.push(t1 - t0);
            statuses[r.status] = (statuses[r.status] || 0) + 1;
          }
          const wait = period - (t1 - t0);
          if (wait > 0) await bru.sleep(wait);
        }
      };
      await Promise.all(Array.from({ length: clients }, client));
      ms.sort((a, b) => a - b);
      const q = (p) => ms.length ? ms[Math.max(0, Math.ceil(p * ms.length) - 1)] : null;
      return { n: ms.length, rps: Math.round((ms.length / seconds) * 10) / 10, p50: q(0.5), p95: q(0.95), max: ms[ms.length - 1], statuses };
    },
  };
  return T;
};
